{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": true,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  }
}

{
  "type": "object",
  "additionalProperties": false,
  "description": "The request to create a lead.\n",
  "properties": {
    "data": {
      "type": "object",
      "additionalProperties": false,
      "description": "The data for the lead request.\n",
      "required": [
        "Name",
        "Email",
        "EmiratesId",
        "MarketingOptOut",
        "ProductCategories"
      ],
      "properties": {
        "Email": {
          "type": "string",
          "format": "email",
          "description": "Email address of the account holder"
        },
        "PhoneNumber": {
          "type": "string",
          "pattern": "^\\+[1-9]\\d{1,14}$",
          "description": "Phone number in E.164 format"
        },
        "Name": {
          "$ref": "#/components/schemas/AEUserName"
        },
        "EmiratesId": {
          "type": "string",
          "pattern": "^784-?[0-9]{4}-?[0-9]{7}-?[0-9]{1}$",
          "description": "Emirates ID number of the Party"
        },
        "Nationality": {
          "type": "string",
          "description": "Nationality of the Party"
        },
        "ResidentialAddress": {
          "$ref": "#/components/schemas/AEResidentialAddress"
        },
        "LeadInformation": {
          "type": "string",
          "description": "Free text information about the lead.\n"
        },
        "MarketingOptOut": {
          "type": "boolean",
          "description": "Whether the lead has opted out of marketing communications."
        },
        "ProductCategories": {
          "$ref": "#/components/schemas/AEProductCategories"
        }
      }
    }
  }
}

{
  "oneOf": [
    {
      "$ref": "#/components/schemas/AEPersonalAccountName"
    },
    {
      "$ref": "#/components/schemas/AEPersonalAccountFullName"
    },
    {
      "$ref": "#/components/schemas/AEBusinessAccountName"
    }
  ],
  "description": "The name of the account holder.\n"
}

{
  "type": "object",
  "required": [
    "GivenName",
    "LastName"
  ],
  "properties": {
    "GivenName": {
      "type": "string",
      "minLength": 1,
      "maxLength": 70,
      "pattern": "^[A-Za-z '.-]+$",
      "description": "The given or first name of the lead"
    },
    "LastName": {
      "type": "string",
      "minLength": 1,
      "maxLength": 70,
      "pattern": "^[A-Za-z '.-]+$",
      "description": "The family or surname of the lead"
    }
  },
  "description": "The name of a personal account",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "FullName"
  ],
  "properties": {
    "FullName": {
      "type": "string",
      "minLength": 1,
      "maxLength": 140,
      "pattern": "^[A-Za-z '.-]+$",
      "description": "The full name of the lead"
    }
  },
  "description": "The full name of a personal account",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "BusinessName"
  ],
  "properties": {
    "BusinessName": {
      "type": "string",
      "minLength": 1,
      "maxLength": 140,
      "pattern": "^[A-Za-z0-9 &'.,()\\/-]+$",
      "description": "The business name of the lead"
    }
  },
  "description": "The name of a business account",
  "additionalProperties": false
}

{
  "description": "Address properties based on ISO 20022 `PostalAddress27` definition",
  "type": "object",
  "required": [
    "AddressLine",
    "Country"
  ],
  "properties": {
    "AddressType": {
      "description": "The type of address. Defaults to `Residential`. Omitted if not held.",
      "type": "string",
      "enum": [
        "Residential"
      ]
    },
    "AddressLine": {
      "description": "Information that locates and identifies a specific address for a transaction entry, that is presented in free format text.",
      "type": "array",
      "minItems": 1,
      "maxItems": 7,
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 70,
        "pattern": "^[A-Za-z0-9 \\/?:().,'+-]+$"
      }
    },
    "BuildingNumber": {
      "description": "The unit, apartment, or villa number within a building or community",
      "type": "string",
      "minLength": 1,
      "maxLength": 16
    },
    "BuildingName": {
      "description": "Name of the building or house.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "Floor": {
      "description": "Floor or storey within a building.",
      "type": "string",
      "minLength": 1,
      "maxLength": 70
    },
    "StreetName": {
      "description": "The name of the street or road where the property is located.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "DistrictName": {
      "description": "The district, community, or neighbourhood where the property is located.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "PostBox": {
      "description": "The P.O. Box number assigned to the recipient for mail delivery.",
      "type": "string",
      "minLength": 1,
      "maxLength": 16
    },
    "TownName": {
      "description": "Name of a built-up area, such as a town or city.",
      "type": "string",
      "minLength": 1,
      "maxLength": 140
    },
    "CountrySubDivision": {
      "description": "Country subdivision, such as state or province. This is the Emirate where the address is registered.",
      "type": "string",
      "enum": [
        "AbuDhabi",
        "Ajman",
        "Dubai",
        "Fujairah",
        "RasAlKhaimah",
        "Sharjah",
        "UmmAlQuwain"
      ]
    },
    "Country": {
      "description": "The country associated with the address, represented using the ISO 3166-1 alpha-2 country code.",
      "type": "string",
      "pattern": "^[A-Z]{2}$"
    }
  },
  "additionalProperties": false
}

{
  "type": "array",
  "description": "The categories of products that are provided or which the lead is interested in.",
  "items": {
    "$ref": "#/components/schemas/AEProductCategoryCodes"
  }
}

{
  "description": "Lead Response",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/LeadResponse"
      }
    }
  }
}

{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "data": {
      "type": "object",
      "description": "The data for the lead response.\n",
      "additionalProperties": false,
      "required": [
        "LeadId",
        "Name",
        "Email",
        "EmiratesId",
        "MarketingOptOut"
      ],
      "properties": {
        "LeadId": {
          "type": "string",
          "description": "Unique identifier for the lead"
        },
        "Email": {
          "type": "string",
          "format": "email",
          "description": "Email address of the account holder"
        },
        "PhoneNumber": {
          "type": "string",
          "pattern": "^\\+[1-9]\\d{1,14}$",
          "description": "Phone number in E.164 format"
        },
        "Name": {
          "$ref": "#/components/schemas/AEUserName"
        },
        "EmiratesId": {
          "type": "string",
          "pattern": "^784-?[0-9]{4}-?[0-9]{7}-?[0-9]{1}$",
          "description": "Emirates ID number of the Party"
        },
        "Nationality": {
          "type": "string"
        },
        "ResidentialAddress": {
          "$ref": "#/components/schemas/AEResidentialAddress"
        },
        "LeadInformation": {
          "type": "string"
        },
        "MarketingOptOut": {
          "type": "boolean",
          "description": "Whether the lead has opted out of marketing communications."
        },
        "ProductCategories": {
          "$ref": "#/components/schemas/AEProductCategories"
        }
      }
    }
  }
}

{
  "description": "Operation failed due to a invalid request parameter",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error400"
      }
    }
  }
}

{
  "description": "Default error response payload structure for Ozone Connect",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation. organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "Consent.Invalid",
            "Consent.BusinessRuleViolation",
            "Consent.FailsControlParameters",
            "Consent.InvalidUserIdentifier",
            "JWS.InvalidSignature",
            "JWS.Malformed",
            "JWS.InvalidClaim",
            "JWS.InvalidHeader",
            "JWE.DecryptionError",
            "JWE.InvalidHeader",
            "GenericRecoverableError",
            "GenericError",
            "Event.UnexpectedEvent",
            "Body.InvalidFormat",
            "Resource.InvalidFormat"
          ]
        },
        {
          "type": "string",
          "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
        },
        {
          "type": "string"
        }
      ]
    },
    "errorMessage": {
      "$ref": "#/components/schemas/ErrorMessage"
    }
  }
}

{
  "description": "Message describing what problem has occurred",
  "type": "string"
}

{
  "description": "The operation failed due to an invalid credential being presented",
  "content": {
    "application/json": {
      "schema": {
        "type": "object",
        "properties": {
          "errorCode": {
            "description": "Error code identifying the problem that occurred. Should be implemented based on guidance in standards and API Hub documentation, but custom error code lists maintained for backwards compatibility with v1.2.",
            "type": "string"
          },
          "errorMessage": {
            "$ref": "#/components/schemas/ErrorMessage"
          }
        }
      }
    }
  }
}

{
  "description": "Operation failed as access to the requested resource is forbidden",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/Error403"
      }
    }
  }
}

{
  "description": "Error code identifying the problem that occurred. The first part of the code is the namespace, which is the name of the organisation or system that is rejecting the payment, and the second part is the specific rejection reason code for the originating organisation or system.\nLFIs should implement error codes based on the prescribed codes or guidance in the standards, with non-specific codes maintained for backward compatibility with version 1.2.",
  "type": "object",
  "required": [
    "errorCode",
    "errorMessage"
  ],
  "properties": {
    "errorCode": {
      "description": "Error code identifying the problem that occurred. This may either be one of the prescribed Error Code(s) or a namespaced Error Code where the namespace is the system or organisation that has responded with the error, and the code is the code specific to the system or organisation.",
      "anyOf": [
        {
          "type": "string",
          "enum": [
            "AccessToken.InvalidScope",
            "Consent.TransientAccountAccessFailure",
            "Consent.AccountTemporarilyBlocked",
            "Consent.PermanentAccountAccessFailure",
            "GenericRecoverableError",
            "GenericError"
          ]
        },
        {
          "type": "string",
          "pattern": "^[A-Za-z]+\\.[A-Za-z0-9]+$"
        },
        {
          "type": "string"
        }
      ]
    },
    "errorMessage": {
      "$ref": "#/components/schemas/ErrorMessage"
    }
  }
}

{
